package in.ac.rtu.medicare.dao;
import in.ac.rtu.medicare.config.Database; import java.sql.*; import java.util.*;
public class ClinicalDao {
 public long saveRecord(long appointmentId,long doctorId,String diagnosis,String notes,List<String[]> drugs)throws SQLException {try(Connection c=Database.connection()){c.setAutoCommit(false);try(PreparedStatement r=c.prepareStatement("INSERT INTO medical_records(appointment_id,diagnosis,notes,created_by) SELECT id,?,?,? FROM appointments WHERE id=? AND doctor_id=? AND status='COMPLETED'",Statement.RETURN_GENERATED_KEYS)){r.setString(1,diagnosis);r.setString(2,notes);r.setLong(3,doctorId);r.setLong(4,appointmentId);r.setLong(5,doctorId);if(r.executeUpdate()!=1)throw new IllegalStateException("Completed appointment is required");try(ResultSet k=r.getGeneratedKeys()){k.next();long id=k.getLong(1);try(PreparedStatement p=c.prepareStatement("INSERT INTO prescriptions(medical_record_id,medicine,dosage,duration,instructions) VALUES(?,?,?,?,?)")){for(String[] d:drugs){p.setLong(1,id);p.setString(2,d[0]);p.setString(3,d[1]);p.setString(4,d[2]);p.setString(5,d.length>3?d[3]:null);p.addBatch();}p.executeBatch();}c.commit();return id;}}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}
}
